INSERT INTO `diseases` (`id`, `name`, `slug`, `description`, `agent_type`, `agent_name`, `family`, `genus`, `incubation_period`, `morbidity_min`, `morbidity_max`, `mortality_min`, `mortality_max`, `zoonotic`, `created_at`, `updated_at`, `deleted_at`) VALUES
('01kvy1vfnyqn1vvtyn6e6dpbjs', 'Avian Encephalomyelitis', 'avian-encephalomyelitis', 'An acute, highly contagious viral disease primarily affecting young birds and characterized by sudden onset of neurological signs including intermittent fine tremors of the head and neck. Infection in older birds is usually subclinical but may result in egg transmission, reduced egg production, and decreased hatchability.', 'virus', 'Avian Encephalomyelitis Virus (AEV)', 'Picornaviridae', 'Enterovirus', '1 to 7 days after vertical transmission and 9 to 16 days after horizontal transmission', 40.00, 60.00, 5.00, 50.00, 0, '2026-06-24 21:11:08', '2026-06-24 21:18:57', NULL),
('01kvy29s4yqaj4k1q8wwpk4bsb', 'Aegyptinellosis', 'aegyptinellosis', 'A blood protozoal disease of poultry caused by Aegyptinella pullorum, characterized by anemia, fever, jaundice, splenomegaly, and hepatic degeneration. The disease is transmitted by Argas persicus ticks.', 'protozoa', 'Aegyptinella pullorum', NULL, 'Aegyptinella', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:56', '2026-06-24 21:18:56', NULL),
('01kvy29se5sete2dg0s3pzfkke', 'Aflatoxicosis', 'aflatoxicosis', 'Aflatoxicosis is a toxicosis caused by aflatoxins, highly hepatotoxic and carcinogenic mycotoxins. The disease primarily affects the liver and results in impaired growth, immunosuppression, poor productivity, and increased mortality.', 'mycotoxin', 'Aflatoxins', NULL, NULL, NULL, NULL, NULL, NULL, 90.00, 0, '2026-06-24 21:18:57', '2026-06-24 21:18:57', NULL),
('01kvy29sn82by5wzwj4nf8c3rh', 'Ascaridiasis', 'ascaridiasis', 'A parasitic disease of poultry caused primarily by Ascaridia galli, characterized by enteritis, poor growth, emaciation, diarrhea, anemia, and reduced productivity. Adult worms mainly inhabit the small intestine but may occasionally be found in other organs.', 'parasite', 'Ascaridia galli', NULL, 'Ascaridia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:57', '2026-06-24 21:18:57', NULL),
('01kvy29sra1rj92hhmbbqndt5q', 'Aspergillosis', 'aspergillosis', 'Aspergillosis is a fungal disease caused by species of the genus Aspergillus. It is usually an acute disease of young birds characterized primarily by respiratory manifestations and occasionally ocular involvement. The disease is commonly associated with poor management and in young birds is referred to as brooder pneumonia.', 'fungus', 'Aspergillus fumigatus', NULL, 'Aspergillus', '8-12 days', NULL, NULL, 10.00, 50.00, 0, '2026-06-24 21:18:57', '2026-06-24 21:18:57', NULL),
('01kvy29sz4y4tverf5p4x6c0ac', 'Avian Coliform Infections', 'avian-coliform-infections', 'A variety of disease conditions resulting from infection of poultry with pathogenic serotypes of Escherichia coli. Infection may be systemic as septicemia or localized in various tissues causing inflammatory lesions.', 'bacterium', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:57', '2026-06-24 21:18:57', NULL),
('01kvy29tdf0fca9k3450mnnkjj', 'Avian Listeriosis', 'avian-listeriosis', 'Avian listeriosis is usually a chronic or subacute bacterial disease affecting domesticated and wild birds, particularly young birds, and is commonly associated with poor management and stress conditions. The disease may occur in septicemic or nervous forms.', 'bacterium', 'Listeria monocytogenes', 'Listeriaceae', 'Listeria', NULL, NULL, 40.00, 30.00, 50.00, 0, '2026-06-24 21:18:58', '2026-06-24 21:18:58', NULL),
('01kvy29tk978fng2j0ph7nnbc4', 'Avian Metapneumovirus Infection', 'avian-metapneumovirus-infection', 'A contagious viral respiratory disease of poultry caused by avian metapneumovirus. In turkeys it is known as turkey rhinotracheitis, while in chickens it is associated with swollen head syndrome and avian rhinotracheitis.', 'virus', 'Avian Metapneumovirus (aMPV)', 'Paramyxoviridae', NULL, NULL, NULL, 100.00, 0.40, 90.00, 0, '2026-06-24 21:18:58', '2026-06-24 21:18:58', NULL),
('01kvy29tqzhr48ywajaqbse84y', 'Avian Pox', 'avian-pox', 'A contagious viral disease of birds characterized by cutaneous eruptions and scab-like lesions on unfeathered skin and/or diphtheritic lesions affecting the mucous membranes of the mouth and upper respiratory tract.', 'virus', 'Avian Pox Virus', 'Poxviridae', 'Avipoxvirus', '4 to 10 days', NULL, 100.00, 3.00, 50.00, 0, '2026-06-24 21:18:58', '2026-06-24 21:18:58', NULL),
('01kvy29v2jzd2cer8fkda9wd30', 'Avian Ringworm', 'avian-ringworm', 'Avian ringworm is a chronic dermatomycosis characterized by the development of thick grayish-white crusts mainly on the comb and wattles, which may extend to the neck and body.', 'fungus', 'Microsporum gallinae', NULL, 'Microsporum', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:58', '2026-06-24 21:18:58', NULL),
('01kvy29v69ephyz1wea1z94kzb', 'Avian Spirochaetosis', 'avian-spirochaetosis', 'Avian spirochaetosis is an acute infectious disease of poultry characterized by fever, locomotor disturbances, progressive paralysis, anemia, and high mortality. The disease is primarily transmitted by avian ticks and other blood-sucking arthropods.', 'bacterium', 'Borrelia anserina', 'Spirochaetaceae', 'Borrelia', '3-9 days', NULL, NULL, 60.00, 90.00, 0, '2026-06-24 21:18:58', '2026-06-24 21:18:58', NULL),
('01kvy29ve7891jnq459ac1j9mv', 'Avian Tuberculosis', 'avian-tuberculosis', 'Avian tuberculosis is a chronic contagious disease of poultry characterized by progressive emaciation, unthriftiness, decreased egg production, and granulomatous lesions in multiple organs.', 'bacterium', 'Mycobacterium avium', 'Mycobacteriaceae', 'Mycobacterium', 'Several months', NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:59', '2026-06-24 21:18:59', NULL),
('01kvy29vmv4a294cbjkqc6k5rs', 'Avian Malaria', 'avian-malaria', 'A blood protozoal disease of poultry caused by several species of Plasmodium and transmitted by mosquitoes. The disease is usually subacute or chronic but may become acute during high parasitemia.', 'protozoa', 'Plasmodium spp.', NULL, 'Plasmodium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:59', '2026-06-24 21:18:59', NULL),
('01kvy29vqy44p87zhatv661zj0', 'Botulism', 'botulism', 'Botulism is an intoxication of poultry caused by neurotoxins produced by Clostridium botulinum. The disease is characterized by progressive flaccid paralysis, especially involving the legs, wings, neck, and eyelids, often resulting in death due to respiratory or cardiac failure.', 'bacterial toxin', 'Neurotoxins produced by Clostridium botulinum', 'Clostridiaceae', 'Clostridium', NULL, NULL, NULL, NULL, 40.00, 0, '2026-06-24 21:18:59', '2026-06-24 21:18:59', NULL),
('01kvy29vwn8t4ayhx6p9j3sz38', 'Candidiasis', 'candidiasis', 'Candidiasis is an opportunistic endogenous chronic mycosis of the upper digestive tract characterized by ulcer-like lesions in the mucosa of the mouth, esophagus, and crop.', 'fungus', 'Candida albicans', NULL, 'Candida', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:59', '2026-06-24 21:18:59', NULL),
('01kvy29w29pdczsfp1c0bnd3nn', 'Cannibalism', 'cannibalism', 'Cannibalism is a behavioral disorder of poultry characterized by pecking and injury of flock mates. It may result in severe economic losses due to hemorrhage, mortality, carcass damage, and reduced productivity.', 'behavioral and managemental disorder', 'Multifactorial behavioral vice', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:59', '2026-06-24 21:18:59', NULL),
('01kvy29w5ab8c9nrpe0mx27jz3', 'Capillariasis', 'capillariasis', 'A highly pathogenic parasitic disease of poultry caused by Capillaria species. The parasites are hair-like nematodes that inhabit various parts of the digestive tract, causing chronic catarrhal inflammation and thickening of the mucosa.', 'parasite', 'Capillaria spp.', 'Trichuridae', 'Capillaria', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:59', '2026-06-24 21:18:59', NULL),
('01kvy29w71bj56avhtqzv24ch4', 'Carbohydrate Nutritional Disorder', 'carbohydrate-nutritional-disorder', 'A nutritional disorder associated with excessive dietary lactose or improper carbohydrate composition in poultry diets. True carbohydrate deficiency is not recognized under practical conditions because cereal grains constitute the major dietary component.', 'nutritional imbalance', 'Excess dietary lactose or inappropriate carbohydrate composition', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:59', '2026-06-24 21:18:59', NULL),
('01kvy29w7xpfgdxh0b4tstxjyc', 'Cecal Worm Infection', 'cecal-worm-infection', 'A parasitic disease of poultry caused by Heterakis species inhabiting the ceca, usually producing subclinical infection but capable of causing typhlitis, cecal necrosis, and cecal core formation in heavy infestations.', 'parasite', 'Heterakis spp.', 'Heterakidae', 'Heterakis', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:18:59', '2026-06-24 21:18:59', NULL),
('01kvy29w97kx9smz6c8gf3rzgp', 'Cestodiasis', 'cestodiasis', 'A parasitic disease of poultry caused by cestodes (tapeworms), which are segmented, band-like helminths lacking an intestinal canal. Development requires intermediate hosts such as snails, slugs, ants, grasshoppers, and beetles.', 'parasite', 'Cestodes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:00', '2026-06-24 21:19:00', NULL),
('01kvy29wbsxz9n1pr7en38kxr4', 'Chicken Infectious Anemia', 'chicken-infectious-anemia', 'A viral disease of young chickens characterized by aplastic anemia, generalized lymphoid atrophy, immunosuppression, and increased susceptibility to secondary infections resulting in poor vaccination response and increased mortality.', 'virus', 'Chicken Infectious Anemia Virus', NULL, 'Gyrovirus', '10 to 14 days experimentally and may extend to 14 to 21 days. Under field conditions, clinical disease usually appears at 10 to 12 days of age with peak mortality at 17 to 24 days.', NULL, NULL, NULL, 60.00, 0, '2026-06-24 21:19:00', '2026-06-24 21:19:00', NULL),
('01kvy29wgpk3jbp92pke9ppb6w', 'Chicks and Turkey Poult Dermatitis', 'chicks-and-turkey-poult-dermatitis', 'A nutritional disorder of chicks and turkey poults characterized by poor growth, ragged feathers, dermatitis, and lesions affecting the skin, beak, eyelids, and feet. In chicks, the condition is associated with pantothenic acid and/or biotin deficiency, whereas in turkey poults it is mainly associated with riboflavin deficiency.', 'nutritional deficiency', 'Pantothenic acid deficiency and/or biotin deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:00', '2026-06-24 21:19:00', NULL),
('01kvy29wr8fnb9krhsht7czw0s', 'Chlamydiosis', 'chlamydiosis-psittacosis-ornithosis', 'Chlamydiosis is a zoonotic infectious disease of domestic and wild birds caused by Chlamydia psittaci. The disease may occur in acute, subacute, or chronic forms and is characterized by respiratory signs and systemic reactions. Psittacosis refers to infection in psittacine birds, whereas ornithosis refers to infection in non-psittacine birds.', 'bacterium', 'Chlamydia psittaci', 'Chlamydiaceae', 'Chlamydia', NULL, NULL, NULL, NULL, 40.00, 0, '2026-06-24 21:19:00', '2026-06-24 21:19:00', NULL),
('01kvy29x4fbe4pg133nw317z6c', 'Choline Deficiency', 'choline-deficiency', 'A nutritional disorder caused by inadequate dietary choline characterized by poor growth and perosis, including hock joint abnormalities, metatarsal deformities, and slippage of the Achilles tendon. Young turkeys are more susceptible than chicks.', 'nutritional deficiency', 'Choline deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:00', '2026-06-24 21:19:00', NULL),
('01kvy29x9tps5z748dvtpq01ha', 'Citrinin', 'citrinin', 'Citrinin is a nephrotoxic mycotoxin naturally contaminating corn, rice, and cereal grains. It primarily affects the kidneys and causes growth depression, reduced feed intake, increased water consumption, and renal tubular damage.', 'mycotoxin', 'Citrinin', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29xc145rd8fgmdfk9tfpt', 'Cobalamin Deficiency', 'cobalamin-deficiency', 'A nutritional disorder caused by inadequate cobalamin intake, characterized by poor growth, reduced feed consumption, decreased egg size, reduced hatchability, embryonic abnormalities, and perosis under conditions of inadequate methyl group donors.', 'nutritional deficiency', 'Cobalamin deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29xfp5e1n2kp5fnmw248v', 'Coccidiosis', 'coccidiosis', 'A protozoal disease caused by several genera, of which Eimeria species are the most economically important, affecting poultry species.', 'protozoa', 'Eimeria spp.', 'Eimeriidae', 'Eimeria', NULL, NULL, NULL, 40.00, 90.00, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29xj7f2q94crg652fxsze', 'Coli Arthritis', 'coli-arthritis', 'A localized Escherichia coli infection of the joints, most commonly affecting the hock joint, often occurring as a sequel to coli septicemia or following local injury.', 'bacterium', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29xna2jeggsspnazx35fd', 'Coli Granuloma', 'coli-granuloma', 'A chronic granulomatous disease of domestic fowl and turkeys characterized by granulomatous lesions resembling those of tuberculosis in the caeca, intestines, liver, and occasionally spleen.', 'bacterium', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29xsjq4y30wgz1w5txmp9', 'Coli Septicemia', 'coli-septicemia', 'An acute septicemic infection of chickens, ducks, and turkeys caused by pathogenic Escherichia coli and characterized particularly by pericarditis and generalized visceral serositis.', 'bacterium', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, 5.00, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29y0enzx900f1h6w60pa9', 'Crimean-Congo Hemorrhagic Fever in Ostriches', 'crimean-congo-hemorrhagic-fever-in-ostriches', 'A tick-borne zoonotic viral disease in ostriches that represents an important public health hazard.', 'virus', 'Crimean-Congo hemorrhagic fever virus', 'Bunyaviridae', 'Nairovirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29y2p4v222fkgb3ecqc80', 'Cryptosporidiosis', 'cryptosporidiosis', 'A protozoal disease of poultry caused by Cryptosporidium baileyi and characterized by respiratory disease, enteritis, diarrhea, and involvement of the cloaca and bursa of Fabricius leading to immunosuppression.', 'protozoa', 'Cryptosporidium baileyi', 'Cryptosporidiidae', 'Cryptosporidium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29y5j4q4rfrznr1zxt1mq', 'Deoxynivalenol Toxicosis', 'deoxynivalenol-toxicosis', 'Deoxynivalenol toxicosis is a trichothecene mycotoxicosis caused by deoxynivalenol (DON, vomitoxin). In poultry, it causes reduced activity, diarrhea, impaired growth and reproduction, and developmental anomalies in progeny.', 'mycotoxin', 'Deoxynivalenol', NULL, 'Fusarium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:01', '2026-06-24 21:19:01', NULL),
('01kvy29yan3svqp1kbpmf5phwr', 'Depluming Mite Infestation', 'depluming-mite-infestation', 'A chronic ectoparasitic skin disease of poultry caused by Knemidocoptes gallinae. The mite invades feathered skin areas, particularly around the tail region, producing intense irritation that leads to feather pulling, feather loss, and skin inflammation.', 'parasite', 'Knemidocoptes gallinae', NULL, 'Knemidocoptes', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:02', '2026-06-24 21:19:02', NULL),
('01kvy29yeeaz4cyszpnqqdf8e0', 'Duck Viral Hepatitis Type 1', 'duck-viral-hepatitis-type-1', 'A highly fatal and highly contagious disease of young ducklings characterized by sudden onset, rapid spread, high mortality and characteristic hemorrhagic liver lesions.', 'virus', 'Duck hepatitis virus type 1', 'Picornaviridae', NULL, '2-3 days', NULL, 100.00, NULL, 95.00, 0, '2026-06-24 21:19:02', '2026-06-24 21:19:02', NULL),
('01kvy29yjr0rc4cfa0p6tw325m', 'Duck Viral Hepatitis Type 2', 'duck-viral-hepatitis-type-2', 'A sporadic astrovirus infection of ducks causing hepatic and renal disease with moderate to high mortality.', 'virus', 'Duck hepatitis virus type 2', 'Astroviridae', NULL, '1-4 days to death after infection', NULL, NULL, 10.00, 50.00, 0, '2026-06-24 21:19:02', '2026-06-24 21:19:02', NULL),
('01kvy29yp4rhhtv6a6zxq320c1', 'Duck Viral Hepatitis Type 3', 'duck-viral-hepatitis-type-3', 'A picornaviral disease of ducks producing clinical signs and lesions similar to DVH type 1 but with lower mortality.', 'virus', 'Duck hepatitis virus type 3', 'Picornaviridae', NULL, NULL, NULL, NULL, NULL, 30.00, 0, '2026-06-24 21:19:02', '2026-06-24 21:19:02', NULL),
('01kvy29yvk239gn286tps2tt87', 'Egg Drop Syndrome', 'egg-drop-syndrome', 'A viral disease affecting laying birds characterized by sudden reduction in egg production and deterioration of egg quality, including shell defects, shell thinning, and shell loss.', 'virus', 'Duck Adenovirus A', 'Adenoviridae', 'Atadenovirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:02', '2026-06-24 21:19:02', NULL),
('01kvy29yykkvafg4xwxrrxx89m', 'Enteritis', 'enteritis', 'A suspected intestinal condition in poultry in which Escherichia coli may invade damaged intestinal mucosa and cause inflammation following predisposing intestinal diseases. Definitive E. coli-induced enteritis has not been proven in domestic poultry.', 'bacterium', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:02', '2026-06-24 21:19:02', NULL),
('01kvy29z0pg6pmf40bmngv4wh3', 'Enzootic Muscular Dystrophy', 'enzootic-muscular-dystrophy', 'A nutritional disorder associated with vitamin E deficiency characterized by degeneration and discoloration of skeletal muscles, particularly in ducklings, resulting in weakness, locomotor impairment, and mortality.', 'nutritional deficiency', 'Vitamin E deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:02', '2026-06-24 21:19:02', NULL),
('01kvy29z517wr0g79kakgczkeb', 'Ergotism', 'ergotism', 'Ergotism is a mycotoxicosis caused by ergot alkaloids produced by Claviceps species. The disease is characterized by vascular, neurologic, and endocrine disorders.', 'mycotoxin', 'Ergot alkaloids', NULL, 'Claviceps', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:02', '2026-06-24 21:19:02', NULL),
('01kvy29z9p0rpacyhm3x4vb3s2', 'Erythroblastosis', 'erythroblastosis', 'A neoplastic disease characterized by proliferation and intravascular accumulation of immature erythroid cells (erythroblasts).', 'virus', 'Avian Leukosis Virus', 'Retroviridae', 'Alpharetrovirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:03', '2026-06-24 21:19:03', NULL),
('01kvy29zfz6erz11587c9dr9r4', 'Essential Fatty Acid Deficiency', 'essential-fatty-acid-deficiency', 'A nutritional disorder caused by inadequate dietary essential fatty acids, particularly linoleic and arachidonic acids, resulting in impaired growth, fatty liver, reduced disease resistance, and decreased reproductive performance.', 'nutritional deficiency', 'Deficiency of essential fatty acids (linoleic acid and arachidonic acid)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:03', '2026-06-24 21:19:03', NULL),
('01kvy29zk7rt7jp5rqpstjhmma', 'Exudative Diathesis', 'exudative-diathesis', 'A nutritional disorder associated with vitamin E deficiency characterized by increased capillary permeability leading to extensive subcutaneous edema, circulatory collapse, and sudden death.', 'nutritional deficiency', 'Vitamin E deficiency', NULL, NULL, NULL, NULL, 80.00, NULL, NULL, 0, '2026-06-24 21:19:03', '2026-06-24 21:19:03', NULL),
('01kvy29zra51g98zf1qhmxv82b', 'Folic Acid Deficiency', 'folic-acid-deficiency', 'A nutritional disorder caused by inadequate folic acid intake or increased folic acid requirements, characterized by perosis, poor feathering, anemia, cervical paralysis in turkeys, and high embryonic mortality.', 'nutritional deficiency', 'Folic acid deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:03', '2026-06-24 21:19:03', NULL),
('01kvy29zvjnkahxkwr801f9che', 'Fowl Tick Infestation', 'fowl-tick-infestation', 'An ectoparasitic infestation of poultry caused by soft ticks of the genus Argas. These nocturnal blood-feeding parasites attack birds during the night and hide in the environment during the day, leading to anemia, weakness, poor growth, and reduced egg production.', 'parasite', 'Argas spp.', 'Argasidae', 'Argas', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:03', '2026-06-24 21:19:03', NULL),
('01kvy29zz37pjvecgz646necb5', 'Fumonisin Toxicosis', 'fumonisin-toxicosis', 'Fumonisin toxicosis is a mycotoxicosis caused by fumonisins produced by Fusarium moniliforme. In poultry, the disease is characterized by digestive disturbances, impaired growth, lymphoid atrophy, and enlargement of several visceral organs.', 'mycotoxin', 'Fumonisin', NULL, 'Fusarium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:03', '2026-06-24 21:19:03', NULL),
('01kvy2a03cv2qzjs60e1d63pxh', 'Fusarium Mycotoxicosis', 'fusarium-mycotoxicosis', 'Fusarium mycotoxicosis is caused by various mycotoxins produced by Fusarium species and is characterized by caustic and radiomimetic injury, cardiac toxicity, and skeletal, digestive, and reproductive disorders.', 'mycotoxin', 'Fusarium mycotoxins', NULL, 'Fusarium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:03', '2026-06-24 21:19:03', NULL),
('01kvy2a069x6ss20etkdf4axed', 'Gangrenous Dermatitis', 'gangrenous-dermatitis', 'Gangrenous dermatitis is an acute bacterial disease of chickens and turkeys characterized by sudden onset of mortality and necrosis of the skin and subcutaneous tissues, particularly affecting the breast, abdomen, wings, and thighs.', 'bacterium', 'Clostridium septicum, Clostridium perfringens type A, and Staphylococcus aureus', 'Clostridiaceae and Staphylococcaceae', 'Clostridium and Staphylococcus', NULL, NULL, NULL, 1.00, 60.00, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a0bsc45qn5n797p5nrem', 'Goose Parvovirus Infection', 'goose-parvovirus-infection', 'A highly contagious viral disease affecting young geese and Muscovy ducks characterized by high mortality, enteritis, myocarditis, growth retardation, and ascites.', 'virus', 'Goose parvovirus', 'Parvoviridae', NULL, '3-5 days in day-old goslings and 5-10 days in older goslings', NULL, 100.00, NULL, 100.00, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a0jbw20d80t6jtgk9296', 'Haemoproteus Infection', 'haemoproteus-infection', 'A blood protozoal disease of pigeons and other birds caused by Haemoproteus species and transmitted by pigeon flies. Infection is usually subclinical but may cause anemia, lameness, diarrhea, and muscular cysts.', 'protozoa', 'Haemoproteus spp.', NULL, 'Haemoproteus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a0p6vn165x294gb0ksjb', 'Heat Stress', 'heat-stress', 'Heat stress is a non-infectious environmental condition that occurs when increased environmental temperature and humidity elevate body temperature beyond the bird\'s ability to dissipate heat. The condition is characterized by panting, increased water intake, dehydration, and may lead to death.', 'environmental', 'High environmental temperature and humidity', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a0rvk4ehmknwt8gg7qc2', 'Hemangioma', 'hemangioma', 'Hemangioma is a vascular neoplasm of poultry that may affect the skin or visceral organs. Lesions may be solitary or multiple and can result in severe hemorrhage if ruptured.', 'neoplasm', 'Hemangioma', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a0t4pqcq8edk17z7tkgd', 'Hexamitiasis', 'hexamitiasis', 'A protozoal enteric disease affecting primarily young turkeys and characterized by enteritis, watery foamy diarrhea, nervousness, and progressive emaciation.', 'protozoa', 'Hexamita meleagridis', NULL, 'Hexamita', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a0vb4bd6716d5c4cb70q', 'Histomoniasis', 'histomoniasis', 'A protozoal disease affecting the ceca and liver of many gallinaceous birds. It is particularly an acute disease of young turkeys characterized by typhlitis, hepatitis, and sulfur-colored diarrhea.', 'protozoa', 'Histomonas meleagridis', NULL, 'Histomonas', NULL, NULL, NULL, NULL, 80.00, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a0x5eycevrjpyenmtbe2', 'Inclusion Body Hepatitis', 'inclusion-body-hepatitis', 'A viral disease affecting young chickens characterized by sudden onset, increased mortality, hepatic lesions with intranuclear inclusion bodies, and immunosuppression.', 'virus', 'Fowl adenovirus', 'Adenoviridae', 'Aviadenovirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a1019v7n767msw8ymfp8', 'Infectious Bronchitis', 'infectious-bronchitis', 'An acute, highly contagious viral disease of chickens characterized by respiratory signs, renal disease caused by nephrotropic strains, decreased egg production, deterioration of egg quality, and reproductive tract abnormalities.', 'virus', 'Infectious Bronchitis Virus (IBV)', 'Coronaviridae', NULL, '1 to 10 days', NULL, 100.00, 5.00, 30.00, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a14xqfmhf30wfdferkvx', 'Infectious Bursal Disease', 'infectious-bursal-disease', 'An acute, highly contagious viral disease of young chickens characterized by profuse whitish diarrhea, depression, ruffled feathers, dehydration, and lesions of the bursa of Fabricius leading to immunosuppression due to destruction of B-lymphocytes.', 'virus', 'Infectious Bursal Disease Virus (IBDV)', 'Birnaviridae', NULL, '3 to 4 days', NULL, 100.00, 5.00, 60.00, 0, '2026-06-24 21:19:04', '2026-06-24 21:19:04', NULL),
('01kvy2a18xwd7jqqvaxn15s0rm', 'Infectious coryza', 'infectious-coryza', 'An acute, rapidly spreading respiratory disease of chickens characterized by nasal discharge, swelling of the eyelids, conjunctivitis, and swelling of the infraorbital sinuses.', 'bacterium', 'Haemophilus paragallinarum', NULL, 'Haemophilus', 'Usually 1-2 days.', NULL, NULL, 0.00, 1.00, 0, '2026-06-24 21:19:05', '2026-06-24 21:19:05', NULL),
('01kvy2a1czmp712p7nyjb0m8s1', 'Infectious Laryngotracheitis', 'infectious-laryngotracheitis', 'A highly contagious viral respiratory disease of chickens caused by Gallid herpesvirus type 1, characterized by respiratory distress, gasping, expectoration of bloody mucus, conjunctivitis, tracheitis, and reduced egg production.', 'virus', 'Gallid herpesvirus type 1 (GaHV-1)', 'Herpesviridae', NULL, NULL, 90.00, 100.00, 5.00, 70.00, 0, '2026-06-24 21:19:05', '2026-06-24 21:19:05', NULL),
('01kvy2a1r2yn3ayp0a7t1mc380', 'Leucocytozoonosis', 'leucocytozoonosis', 'A blood protozoal disease affecting blood and tissue cells of internal organs of birds and transmitted by blood-sucking insects. The disease affects ducks, chickens, and turkeys and may cause anemia, weakness, hemorrhages, decreased production, and sudden death.', 'protozoa', 'Leucocytozoon spp.', NULL, 'Leucocytozoon', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:05', '2026-06-24 21:19:05', NULL),
('01kvy2a1yrpzscywkme4fb7z1s', 'Lice Infestation', 'lice-infestation', 'A permanent ectoparasitic infestation of poultry caused by chewing lice. Lice are wingless, flattened insects possessing three pairs of legs and biting-chewing mouthparts. The entire life cycle occurs on the host bird.', 'parasite', 'Chewing lice', NULL, NULL, 'Eggs hatch in approximately 1 week. The complete life cycle takes 2-3 weeks.', NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:05', '2026-06-24 21:19:05', NULL),
('01kvy2a220e4s2zbg4afndq8rs', 'Lymphoid Leukosis', 'lymphoid-leukosis', 'A lymphoproliferative neoplastic disease affecting primarily the bursa of Fabricius and visceral organs and caused by avian leukosis virus-related retroviruses.', 'virus', 'Avian Leukosis Virus', 'Retroviridae', 'ALV-related viruses', 'Lymphoid leukosis usually appears between 14 and 30 weeks of age and rarely before 14 weeks.', NULL, NULL, 1.00, 20.00, 0, '2026-06-24 21:19:05', '2026-06-24 21:19:05', NULL),
('01kvy2a2852t0dzn0xm1dnh4ge', 'Marek\'s Disease', 'mareks-disease', 'A lymphoproliferative disease affecting the peripheral nervous system, gonads, iris, various visceral organs, muscles and skin. It is caused by an alphaherpesvirus and mainly affects T lymphocytes.', 'virus', 'Marek\'s Disease Virus', 'Herpesviridae', 'Mardivirus', 'Clinical signs usually begin 3-4 weeks post infection. Virus shedding starts approximately 2 weeks post infection.', NULL, 60.00, NULL, NULL, 0, '2026-06-24 21:19:06', '2026-06-24 21:19:06', NULL),
('01kvy2a2dq9nkj7txpgafm2t1r', 'Moniliformin Toxicosis', 'moniliformin-toxicosis', 'Moniliformin toxicosis is a mycotoxicosis caused by moniliformin produced by Fusarium moniliforme and other Fusarium species. The disease is characterized by cardiotoxicity, nephrotoxicity, ascites, impaired growth, and reproductive disturbances.', 'mycotoxin', 'Moniliformin', NULL, 'Fusarium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:06', '2026-06-24 21:19:06', NULL),
('01kvy2a2q0mqsgzkn1j16y2vsm', 'Mycoplasma Gallisepticum Infection', 'mycoplasma-gallisepticum-infection', 'A worldwide, slowly spreading, persistent respiratory disease of chickens and turkeys caused by Mycoplasma gallisepticum. The disease is commonly referred to as chronic respiratory disease (CRD) in chickens and infectious sinusitis in turkeys and is associated with significant economic losses due to poor growth, reduced egg production, decreased hatchability, and carcass condemnation.', 'bacterium', 'Mycoplasma gallisepticum', 'Mycoplasmataceae', 'Mycoplasma', '11-18 days', NULL, NULL, 0.00, 30.00, 0, '2026-06-24 21:19:06', '2026-06-24 21:19:06', NULL),
('01kvy2a2z9bmqpx4am37g5fnkt', 'Mycoplasma meleagridis Infection', 'mycoplasma-meleagridis-infection', 'An egg-transmitted infectious disease of turkeys caused by Mycoplasma meleagridis. The disease is characterized by poor growth, airsacculitis in young poults, reduced hatchability, and carcass condemnations due to air sac lesions.', 'bacterium', 'Mycoplasma meleagridis', 'Mycoplasmataceae', 'Mycoplasma', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:06', '2026-06-24 21:19:06', NULL),
('01kvy2a32eqwdegf3dj8t0r64v', 'Mycoplasma Synoviae Infection', 'mycoplasma-synoviae-infection', 'An acute to chronic infectious disease of chickens and turkeys caused by Mycoplasma synoviae. The disease primarily affects synovial membranes, tendon sheaths, and bursae, resulting in exudative synovitis, tenosynovitis, and bursitis. Upper respiratory tract infection is usually subclinical, but the organism is also associated with chronic airsacculitis and respiratory disease in chickens.', 'bacterium', 'Mycoplasma synoviae', 'Mycoplasmataceae', 'Mycoplasma', NULL, 2.00, 75.00, 1.00, 10.00, 0, '2026-06-24 21:19:06', '2026-06-24 21:19:06', NULL),
('01kvy2a3emhjgb3sfh5br5vhy4', 'Myeloblastosis', 'myeloblastosis', 'A sporadic neoplastic disease of mature birds characterized by massive intravascular and extravascular accumulation of myeloblasts.', 'virus', 'Avian Leukosis Virus', 'Retroviridae', 'Alpharetrovirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:07', '2026-06-24 21:19:07', NULL),
('01kvy2a3gergnh8vxmythfgkex', 'Myelocytomatosis', 'myelocytomatosis', 'A neoplastic disease characterized by tumors composed of uniform well-differentiated myelocytes.', 'virus', 'Avian Leukosis Virus subgroup J', 'Retroviridae', 'Alpharetrovirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:07', '2026-06-24 21:19:07', NULL),
('01kvy2a3kv1z20nyjaj9qfrj96', 'Myxomatosis', 'myxomatosis', 'A highly contagious viral disease of wild and domestic rabbits caused by myxoma virus and characterized by edema of the eyelids, head and genitalia, blepharoconjunctivitis, myxoma formation, and high mortality.', 'virus', 'Myxoma virus', 'Poxviridae', NULL, '3 to 14 days', NULL, NULL, NULL, 100.00, 0, '2026-06-24 21:19:07', '2026-06-24 21:19:07', NULL),
('01kvy2a3vpsvspwmnrqxejnr70', 'Necrotic Enteritis', 'necrotic-enteritis', 'Necrotic enteritis is a severe disease of avian species characterized by necrosis of the intestinal mucosa.', 'bacterium', 'Clostridium perfringens', NULL, 'Clostridium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:07', '2026-06-24 21:19:07', NULL),
('01kvy2a402kbwv6rcc30yjd9zr', 'Nephroblastoma', 'nephroblastoma', 'Nephroblastoma is a renal neoplasm of poultry characterized by nodular to massive tumors replacing renal tissue.', 'neoplasm', 'Nephroblastoma', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:07', '2026-06-24 21:19:07', NULL),
('01kvy2a4485x8ap49jnfmgm5km', 'Niacin Deficiency', 'niacin-deficiency', 'A nutritional disorder resulting from inadequate dietary niacin or tryptophan, characterized by poor growth, hock enlargement, bowed legs, oral inflammation, diarrhea, poor feathering, and reduced reproductive performance. Ducks are particularly susceptible because of their high niacin requirement.', 'nutritional deficiency', 'Niacin deficiency', NULL, NULL, 'Approximately 2 weeks in chicks fed diets deficient in both niacin and tryptophan.', NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:08', '2026-06-24 21:19:08', NULL),
('01kvy2a4atrpg7p9cawgbsqv10', 'Northern Fowl Mite Infestation', 'northern-fowl-mite-infestation', 'A permanent ectoparasitic infestation of poultry caused by Ornithonyssus sylviarum. It is considered the most common and economically important mite infestation of poultry. The mites are blood feeders and heavy infestations adversely affect productivity, immunity, and reproductive performance.', 'parasite', 'Ornithonyssus sylviarum', NULL, 'Ornithonyssus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:08', '2026-06-24 21:19:08', NULL),
('01kvy2a4dn4szmztvwgnyc275b', 'Ochratoxicosis', 'ochratoxicosis', 'Ochratoxicosis is a mycotoxicosis caused by ochratoxins, primarily affecting the kidneys but also influencing hepatic, immunologic, and hematopoietic functions.', 'mycotoxin', 'Ochratoxin A', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:08', '2026-06-24 21:19:08', NULL),
('01kvy2a4q91s0gsfc4v61wfz8g', 'Omphalitis', 'omphalitis', 'An infection of the navel in newly hatched chicks or poults caused by Escherichia coli, usually resulting from contamination of eggshells or incubators and characterized by inflammation of the navel, weakness, and high mortality.', 'bacterium', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:08', '2026-06-24 21:19:08', NULL),
('01kvy2a4vjxbknrv64zd3cvxvw', 'Oosporein Toxicosis', 'oosporein-toxicosis', 'Oosporein toxicosis is a mycotoxicosis caused by oosporein, a red toxic metabolite produced mainly by Chaetomium trilaterale and Oospora colorans. The disease is characterized by nephrotoxicity, visceral gout, high mortality, and reduced productivity.', 'mycotoxin', 'Oosporein', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:08', '2026-06-24 21:19:08', NULL),
('01kvy2a512d6xqjyqccyfgeb7q', 'Osteopetrosis', 'osteopetrosis', 'A sporadic condition characterized by progressive bilateral thickening of long bones.', 'virus', 'Avian Leukosis Virus-associated', 'Retroviridae', 'Alpharetrovirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:08', '2026-06-24 21:19:08', NULL),
('01kvy2a548gqyrbx5n5fsdw82b', 'Ostrich Adenovirus Infection', 'ostrich-adenovirus-infection', 'Adenovirus-associated disease of ostriches characterized by wasting, anorexia and depression, particularly in young birds.', 'virus', 'Avian adenoviruses', 'Adenoviridae', 'Aviadenovirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:09', '2026-06-24 21:19:09', NULL),
('01kvy2a592b6912bee7ae45y3j', 'Anthrax of Ostriches', 'ostrich-anthrax', 'Anthrax is a peracute or acute febrile infectious disease of ostriches caused by Bacillus anthracis and characterized by rapid fatal septicemia, sudden death, and exudation of tarry blood from body orifices.', 'bacteria', 'Bacillus anthracis', 'Bacillaceae', 'Bacillus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:09', '2026-06-24 21:19:09', NULL),
('01kvy2a5gz429xf7bwx32wwh7g', 'Ostrich Avian Influenza', 'ostrich-avian-influenza', 'A highly contagious viral disease of ostriches caused by influenza A viruses and characterized mainly by respiratory disease, green urine, sudden death and high mortality in young ostriches.', 'virus', 'Avian Influenza Virus', 'Orthomyxoviridae', 'Influenzavirus A', NULL, NULL, 100.00, NULL, 60.00, 0, '2026-06-24 21:19:09', '2026-06-24 21:19:09', NULL),
('01kvy2a5sdyh7e4tspcdnrqdeq', 'Borna Disease', 'ostrich-borna-disease', 'A viral neurotropic disease affecting mainly young ostrich chicks causing paresis, paralysis and high mortality.', 'virus', 'Borna disease virus', 'Rhabdoviridae', NULL, 'Less than 2 months', NULL, NULL, 2.00, 20.00, 0, '2026-06-24 21:19:09', '2026-06-24 21:19:09', NULL),
('01kvy2a5vrg12f85skhhbqky76', 'Botulism of Ostriches', 'ostrich-botulism', 'A fatal intoxication of ostriches caused by ingestion of botulinum toxin, most commonly Clostridium botulinum type C toxin, characterized by progressive paralysis and death.', 'bacterial_toxin', 'Clostridium botulinum type C toxin', 'Clostridiaceae', 'Clostridium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:09', '2026-06-24 21:19:09', NULL),
('01kvy2a5zr8r5h09jwwg08z1ee', 'Campylobacteriosis of Ostriches', 'ostrich-campylobacteriosis', 'Campylobacteriosis is a severe bacterial disease of ostriches caused by Campylobacter jejuni. The disease may be semi-acute or chronic and mainly affects young ostriches between 10 days and 4 months of age, resulting in increased mortality.', 'bacteria', 'Campylobacter jejuni', 'Campylobacteraceae', 'Campylobacter', NULL, NULL, NULL, 40.00, 40.00, 0, '2026-06-24 21:19:09', '2026-06-24 21:19:09', NULL),
('01kvy2a66pxktyvaf53yh09953', 'Ostrich Coccidiosis', 'ostrich-coccidiosis', 'A protozoal disease of the digestive tract of ostriches caused by Eimeria species. The disease occurs worldwide, particularly in ostrich chicks reared indoors. Clinical significance in ostriches has not yet been fully established.', 'protozoan_parasite', 'Eimeria spp.', NULL, 'Eimeria', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a69depbagqhygwem7jqz', 'Codiostomum struthionis Infection', 'codiostomum-struthionis-infection', 'A nematode infection of ostriches caused by Codiostomum struthionis. The parasite is specific to ostriches and inhabits the large intestine where it interferes with water absorption. Clinical manifestations are usually absent or non-specific.', 'parasite', 'Codiostomum struthionis', NULL, 'Codiostomum', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a6atjr91t2f63ta6xeq7', 'Ostrich Coronavirus Enteritis', 'ostrich-coronavirus-enteritis', 'An enteric disease of young ostriches associated with chronic fading syndrome or explosive outbreaks.', 'virus', 'Ostrich coronavirus', 'Coronaviridae', 'Coronavirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a6c94bbjt906ggw9tjyg', 'Ostrich Degenerative Myopathy', 'ostrich-degenerative-myopathy', 'A non-infectious musculoskeletal disorder of young ostriches characterized by degeneration of skeletal and cardiac muscles. The condition is associated with selenium or vitamin E deficiency, furazolidone toxicity, ionophore toxicity, and certain toxic plants.', 'multifactorial', 'Selenium deficiency, vitamin E deficiency, furazolidone toxicity, ionophore toxicity, and toxic plants', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a6evsn040x0023takt8t', 'Ostrich Ectoparasitism', 'ostrich-ectoparasitism', 'A group of infestations caused by external parasites including lice, mites and ticks affecting ostriches of all ages. These parasites cause irritation, feather damage, skin lesions, poor performance and may transmit other diseases.', 'parasites', 'External parasites', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a6khak0z8ztkfbjsn4bz', 'Ostrich Egg Bound', 'ostrich-egg-bound', 'A reproductive disorder in ostrich hens characterized by inability to expel a fully formed egg from the reproductive tract.', 'multifactorial', 'Multifactorial reproductive disorder', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a6q66akrc0gh74n190ye', 'Ostrich Eye Fluke Infection', 'ostrich-eye-fluke-infection', 'A parasitic disease of ostriches and other birds caused by eye flukes that inhabit the conjunctival sac, leading to conjunctivitis and excessive lacrimation.', 'parasite', 'Eye fluke', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a6t7b9jmzygsee5y62va', 'Feather Pecking and Cannibalism', 'feather-pecking-and-cannibalism', 'A multifactorial behavioral disorder of ostriches characterized by pecking at feathers, wings, toes, nose and other body parts, resulting in feather loss, injuries, reduced market value and outbreaks of cannibalism in captive ostriches.', 'behavioral_disorder', 'Multifactorial management and nutritional disorder', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a6zs9799nq5kydwjf0hy', 'Ostrich Fractures', 'ostrich-fractures', 'A common non-infectious musculoskeletal disorder of ostriches characterized by fractures, particularly of the legs and wings. Fractures are frequently associated with improper restraint, excessive body weight, and physical stress.', 'non_infectious', 'Traumatic bone injury', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:10', '2026-06-24 21:19:10', NULL),
('01kvy2a72wm57wgv3ntfvw0bt1', 'Ostrich Hypothermia', 'ostrich-hypothermia', 'A non-infectious condition in ostriches caused by prolonged exposure to low environmental temperatures resulting in hypothermia, stunting, cardiovascular disturbances and death, particularly in young ostrich chicks.', 'non_infectious', 'Prolonged exposure to low environmental temperature', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a74hpk1mhke9nvvd16n2', 'Ostrich Induced Nervous Disorder', 'ostrich-induced-nervous-disorder', 'A group of neurological disorders in ostriches resulting from toxic, infectious, metabolic, environmental, traumatic, or nutritional causes. Clinical manifestations vary according to the underlying etiology and commonly include ataxia, tremors, seizures, anorexia, and other nervous signs.', 'multifactorial', 'Toxins, infectious agents, metabolic disorders, environmental factors and trauma', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a78cnwwwfpzjpdr7qbqh', 'Ostrich Infectious Bursal Disease', 'ostrich-infectious-bursal-disease', 'A birnaviral disease reported in immature ostriches characterized by diarrhea, enteritis, bursal atrophy and nervous manifestations.', 'virus', 'Infectious Bursal Disease Virus', 'Birnaviridae', 'Avibirnavirus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a7be7xbnk4nyh7g68dy7', 'Ostrich Ingested Toxicosis', 'ostrich-ingested-toxicosis', 'A toxic condition in ostriches caused by ingestion of toxic beetles associated with trees and alfalfa hay, resulting primarily in enteritis and significant mortality.', 'toxin', 'Toxins from ingested beetles', NULL, NULL, NULL, NULL, NULL, NULL, 25.00, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a7ebgwyp3as84wd8r8ne', 'Ostrich Intestinal Torsion', 'ostrich-intestinal-torsion', 'A non-infectious gastrointestinal disorder in ostriches characterized by twisting of the intestines. The condition may occur sporadically or as an outbreak and may result in significant mortality. Dietary changes, particularly switching from pelleted feed to chopped leaves, have been implicated as a predisposing factor.', 'non_infectious', 'Twisting of the intestines', NULL, NULL, NULL, NULL, 25.00, NULL, 25.00, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a7fktyshxnsbmkyhhy04', 'Ostrich Intussusception', 'ostrich-intussusception', 'A non-infectious gastrointestinal disorder in ostriches characterized by invagination of one segment of the intestine into an adjacent segment. The condition is associated with intestinal hypermotility and irritation, usually following sudden dietary changes or diets containing high fiber levels.', 'non_infectious', 'Intestinal hypermotility and irritation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a7h0tg4dhswxam2jkdzs', 'Ostrich Liver and Oviduct Neoplasia', 'ostrich-liver-and-oviduct-neoplasia', 'Neoplastic disease in ostriches characterized by lymphoid tumors involving the liver and oviduct, accompanied by systemic illness and hematological abnormalities.', 'unknown', 'Undetermined; possible association with leukosis-like viruses', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a7m1c24gkeyh66m079c6', 'Manganese Deficiency in Ostriches', 'ostrich-manganese-deficiency', 'A nutritional disorder in ostriches caused by insufficient dietary manganese or impaired manganese absorption. The disease is characterized by skeletal deformities, perosis, poor eggshell quality, reduced egg production, embryonic malformations, and neurological signs.', 'nutritional_deficiency', 'Manganese deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a7tdm9z25csvvygcjwp7', 'Necrotic or Ulcerative Enteritis of Ostriches', 'ostrich-necrotic-ulcerative-enteritis', 'An acute clostridial disease affecting ostriches of any age, mainly caused by Clostridium perfringens type C and Clostridium colinum, characterized by acute enteritis, depression, sudden death, and high mortality.', 'bacteria', 'Clostridium perfringens type C and Clostridium colinum', 'Clostridiaceae', 'Clostridium', NULL, NULL, NULL, NULL, 100.00, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a7z7h8q4sgtz4yqr5zqg', 'Ostrich Newcastle Disease', 'ostrich-newcastle-disease', 'A viral, infectious and highly contagious disease affecting ostriches and other ratites causing respiratory and nervous disorders with high mortality particularly in young ostriches.', 'virus', 'Newcastle Disease Virus', 'Paramyxoviridae', 'Rubulavirus', '2 to 15 days after exposure.', NULL, NULL, 30.00, 85.00, 0, '2026-06-24 21:19:11', '2026-06-24 21:19:11', NULL),
('01kvy2a86z4d0ec1breyh4chz2', 'Omphalitis and Yolk Sacculitis of Ostriches', 'ostrich-omphalitis-yolk-sacculitis', 'A bacterial disease of ostrich chicks characterized by inflammation of the navel, retained yolk sac, incomplete yolk sac absorption, and high mortality before and after hatching.', 'bacteria', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8b4vn65zt6fc12q95es', 'Ostrich Parsley-Induced Photosensitivity', 'ostrich-parsley-induced-photosensitivity', 'A non-infectious phototoxic disorder of ostriches caused by ingestion of parsley (Petroselinum sativum). The condition is characterized by photosensitivity with skin lesions predominantly affecting exposed areas.', 'plant_toxicosis', 'Petroselinum sativum', NULL, 'Petroselinum', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8f7svd1z61s9mcs51w2', 'Ostrich Peritoneal Hernia', 'ostrich-peritoneal-hernia', 'A non-infectious condition in ostriches characterized by herniation of abdominal organs, particularly intestines and uterus, into the pericloacal region of the caudal abdominal cavity.', 'non_infectious', 'Herniation of abdominal organs', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8g2wph7yc92xjv515d6', 'Ostrich Phallus Prolapse', 'ostrich-phallus-prolapse', 'A reproductive disorder of male ostriches characterized by complete protrusion of the phallus outside the cloaca. While partial prolapse may occur normally in sexually active breeding males, complete prolapse is considered pathological and may result in trauma, necrosis, and dermatitis.', 'multifactorial', 'Unknown', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8h2eh4fcw98sd2111wh', 'Ostrich Pneumonia', 'ostrich-pneumonia', 'A respiratory disease of ostriches affecting the lower respiratory tract. Pneumonia may be caused by bacterial or fungal agents, particularly Aspergillus spp., and is characterized by respiratory distress and lower respiratory tract lesions.', 'multifactorial', 'Bacterial agents and Aspergillus infections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL);
INSERT INTO `diseases` (`id`, `name`, `slug`, `description`, `agent_type`, `agent_name`, `family`, `genus`, `incubation_period`, `morbidity_min`, `morbidity_max`, `mortality_min`, `mortality_max`, `zoonotic`, `created_at`, `updated_at`, `deleted_at`) VALUES
('01kvy2a8k0qc0mstns50s0c1ex', 'Ostrich Pox', 'ostrich-pox', 'A viral disease of ostriches characterized by cutaneous wart-like lesions and diphtheritic lesions of the upper digestive and respiratory tracts.', 'virus', 'Avipoxvirus', 'Poxviridae', 'Avipoxvirus', '6-10 days', NULL, NULL, NULL, 15.00, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8pzaxm3xbkt8mzwpd3q', 'Salmonellosis of Ostriches', 'ostrich-salmonellosis', 'A bacterial disease of ostriches caused by various Salmonella species and characterized by high embryonic losses, diarrhea, depression, omphalitis, hepatosplenomegaly, and congestion.', 'bacteria', 'Salmonella spp.', 'Enterobacteriaceae', 'Salmonella', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8rjda8cbr8drqk143f7', 'Ostrich Tapeworm Infection', 'ostrich-tapeworm-infection', 'A parasitic disease of ostriches caused by the cestode Houttuynia struthionis. The parasite inhabits the small intestine, particularly affecting young ostrich chicks, causing unthriftiness, emaciation, and increased mortality.', 'parasite', 'Houttuynia struthionis', NULL, 'Houttuynia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8ss3374zfzh22wyzk2f', 'Trauma', 'trauma', 'A common non-infectious condition in ostriches resulting from physical injury. Trauma is considered the major single cause of mortality in ostriches older than three months of age and is commonly associated with improper handling, poor facility design, and transportation stress.', 'non_infectious', 'Physical injury', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8vjb7e5hdp5dajhadzs', 'Ostrich Vaginal Prolapse', 'ostrich-vaginal-prolapse', 'A reproductive disorder of female ostriches characterized by protrusion of the vaginal tissue outside the cloaca. The condition may occur even in hens younger than one year of age and may be associated with exposure to cold temperatures.', 'non_infectious', 'Unknown', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8wfg8xbf962gzyzxefa', 'Vitamin A Deficiency in Ostriches', 'ostrich-vitamin-a-deficiency', 'A nutritional disorder in ostriches caused by inadequate dietary vitamin A, characterized by impaired growth, reduced productivity, keratinization of mucous membranes, ocular lesions, respiratory disease, and skeletal abnormalities.', 'nutritional_deficiency', 'Vitamin A deficiency', NULL, NULL, 'Clinical signs and lesions usually develop within 2-3 months in adult birds fed a vitamin A deficient diet.', NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a8yh8mktkvv5cebg9ksk', 'Vitamin B Deficiency in Ostriches', 'ostrich-vitamin-b-deficiency', 'A nutritional disorder in ostriches resulting from deficiencies of B-complex vitamins, particularly riboflavin, biotin, and pantothenic acid. The disease affects growth, nervous system function, metabolism, feathering, and reproduction.', 'nutritional_deficiency', 'Vitamin B complex deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:12', '2026-06-24 21:19:12', NULL),
('01kvy2a90qy4fw6nf4zxnjd8rj', 'Vitamin D Deficiency in Ostriches', 'ostrich-vitamin-d-deficiency', 'A nutritional disorder in ostriches caused by inadequate vitamin D, leading to impaired calcium and phosphorus absorption, skeletal abnormalities, poor growth, reduced egg production, and poor eggshell quality.', 'nutritional_deficiency', 'Vitamin D deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:13', '2026-06-24 21:19:13', NULL),
('01kvy2a92sfa2vfgnksnryvhcc', 'Vitamin E Deficiency in Ostriches', 'ostrich-vitamin-e-deficiency', 'A nutritional disorder in ostriches caused by inadequate dietary vitamin E, often influenced by selenium status. The disease primarily affects growing ostriches and breeding birds, resulting in neurological disorders, edema, muscular degeneration, reproductive failure, and reduced hatchability.', 'nutritional_deficiency', 'Vitamin E deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:13', '2026-06-24 21:19:13', NULL),
('01kvy2a954cyxcvrr2sqhdykwz', 'Ostrich Wireworm Infection', 'ostrich-wireworm-infection', 'An economically important parasitic disease of ostriches caused by the nematode Libyostrongylus douglassi. The parasite inhabits the glandular portion of the proventriculus causing severe pathological changes, proventricular impaction, anemia, digestive disturbances, and high mortality particularly in young ostrich chicks.', 'parasite', 'Libyostrongylus douglassi', NULL, 'Libyostrongylus', 'Approximately 3 weeks from ingestion of infective larvae to development of adult worms. Third-stage larvae develop to mature worms in approximately 29 days.', NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:13', '2026-06-24 21:19:13', NULL),
('01kvy2a97d9x788q7xqyz2gzzg', 'Panophthalmitis', 'panophthalmitis', 'An uncommon manifestation of Escherichia coli infection resulting from bacteremia and characterized by severe ocular inflammation, blindness, hyperemia of the choroid, and complete retinal destruction.', 'bacterium', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:13', '2026-06-24 21:19:13', NULL),
('01kvy2a997s5qsn1kd1jvy84g4', 'Pigeon Circovirus Infection', 'pigeon-circovirus-infection', 'A circoviral disease of pigeons characterized by immunosuppression, respiratory disease, weight loss, diarrhea, reduced racing performance, feather abnormalities, and variable mortality.', 'virus', 'Pigeon Circovirus', 'Circoviridae', 'Circovirus', NULL, NULL, NULL, 1.00, 100.00, 0, '2026-06-24 21:19:13', '2026-06-24 21:19:13', NULL),
('01kvy2a9d840wbkf3ztjd4jjk7', 'Protein and Amino Acid Deficiency', 'protein-and-amino-acid-deficiency', 'A nutritional disorder resulting from inadequate dietary protein or deficiency of one or more essential amino acids, leading to impaired growth, reduced productivity, poor feathering, and metabolic disturbances in poultry.', 'nutritional deficiency', 'Deficiency of dietary protein and/or essential amino acids', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:13', '2026-06-24 21:19:13', NULL),
('01kvy2a9j1q4h0097eqjhc09dg', 'Quail Bronchitis', 'quail-bronchitis', 'An acute, highly contagious, and frequently fatal respiratory disease of young bobwhite quail characterized by sudden onset, high morbidity, high mortality, and severe respiratory lesions.', 'virus', 'Quail Bronchitis Virus', 'Adenoviridae', NULL, '2 to 11 days, most commonly 3 to 7 days.', NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:13', '2026-06-24 21:19:13', NULL),
('01kvy2a9t5zcps36xyayprvf29', 'Rabbit Coccidiosis', 'rabbit-coccidiosis', 'Rabbit coccidiosis is an acute, subacute, or chronic protozoal disease of rabbits characterized by diarrhea, salivation, bloat, and emaciation. The disease occurs in two forms: hepatic and intestinal coccidiosis.', 'protozoan', 'Eimeria spp.', 'Eimeriidae', 'Eimeria', NULL, NULL, NULL, 70.00, 90.00, 0, '2026-06-24 21:19:13', '2026-06-24 21:19:13', NULL),
('01kvy2aa0h7gzzv6payb8gk8jv', 'Rabbit Mange', 'rabbit-mange', 'Rabbit mange is a highly contagious parasitic disease causing severe skin irritation, crust formation, emaciation, and economic losses due to skin damage and reduced productivity. Two major forms occur in rabbits: ear mange and body mange.', 'ectoparasite', 'Mange mites', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:14', '2026-06-24 21:19:14', NULL),
('01kvy2aa5ra3pn544j0rt179cz', 'Rabbit Viral Hemorrhagic Disease', 'rabbit-viral-hemorrhagic-disease', 'An acute or peracute highly contagious and highly fatal viral disease of rabbits caused by a calicivirus and characterized by sudden death, fever, hemorrhages, severe hepatic necrosis, respiratory distress, and disseminated intravascular coagulation.', 'virus', 'Rabbit Viral Hemorrhagic Disease Virus', 'Caliciviridae', NULL, '12 to 72 hours', NULL, NULL, 80.00, 90.00, 0, '2026-06-24 21:19:14', '2026-06-24 21:19:14', NULL),
('01kvy2aaqchq9nerbx988fe7z6', 'Red Mite Infestation', 'red-mite-infestation', 'An ectoparasitic infestation of poultry caused by Dermanyssus gallinae. The red mite is an intermittent blood-feeding ectoparasite that attacks birds mainly at night and can survive for several months without feeding. Heavy infestations cause irritation, anemia, and production losses.', 'parasite', 'Dermanyssus gallinae', NULL, 'Dermanyssus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:14', '2026-06-24 21:19:14', NULL),
('01kvy2aawb7rgq82wgkwvz8qd1', 'Reticuloendotheliosis', 'reticuloendotheliosis', 'A group of pathogenic syndromes caused by reticuloendotheliosis viruses including acute reticulum cell neoplasia, runting disease syndrome, and chronic neoplasia affecting lymphoid and other tissues.', 'virus', 'Reticuloendotheliosis Virus', NULL, 'Murine leukemia virus-related retrovirus', 'May be as short as 3 days. Death commonly occurs 6-21 days post inoculation in acute disease.', NULL, NULL, NULL, 100.00, 0, '2026-06-24 21:19:14', '2026-06-24 21:19:14', NULL),
('01kvy2ab3ne0mc4xyssg237hbx', 'Riboflavin Deficiency', 'riboflavin-deficiency', 'A nutritional disorder caused by inadequate dietary riboflavin characterized by poor growth, weakness, leg paralysis, inability to walk, and inward curling of the toes, particularly in young birds.', 'nutritional deficiency', 'Riboflavin deficiency', NULL, NULL, 'Approximately 2 weeks in adult birds for reproductive effects.', NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:15', '2026-06-24 21:19:15', NULL),
('01kvy2abg9wp5d0dh6jgt7gng6', 'Riemerella anatipestifer infection', 'riemerella-anatipestifer-infection', 'An acute or chronic septicemic disease primarily affecting ducks and geese, characterized by serofibrinous pericarditis, perihepatitis, airsacculitis, salpingitis, and meningitis.', 'bacterium', 'Riemerella anatipestifer', NULL, 'Riemerella', '2-5 days', NULL, NULL, 5.00, 75.00, 0, '2026-06-24 21:19:15', '2026-06-24 21:19:15', NULL),
('01kvy2absekaa4cb74nh18ejnk', 'Salpingitis', 'salpingitis', 'An inflammation of the oviduct caused by various serotypes of Escherichia coli, commonly occurring in chickens at the onset of lay and leading to reproductive dysfunction, internal laying, and egg peritonitis.', 'bacterium', 'Escherichia coli', NULL, 'Escherichia', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:15', '2026-06-24 21:19:15', NULL),
('01kvy2abwx3r42k8fx96xj60by', 'Scaly Leg Mite Infestation', 'scaly-leg-mite-infestation', 'A contagious ectoparasitic disease caused by Knemidocoptes mutans and characterized by chronic dermatitis, pruritus, thickening of the shanks, and accumulation of dry grayish debris beneath loosened scales.', 'parasite', 'Knemidocoptes mutans', NULL, 'Knemidocoptes', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:15', '2026-06-24 21:19:15', NULL),
('01kvy2ac22h9xdwnqga290ycef', 'Snuffles', 'snuffles', 'Snuffles is an acute, subacute, or chronic pasteurellosis of rabbits characterized by respiratory distress in acute and subacute forms and by subcutaneous abscess formation in chronic cases.', 'bacterium', 'Pasteurella multocida', 'Pasteurellaceae', 'Pasteurella', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:16', '2026-06-24 21:19:16', NULL),
('01kvy2acdrb35rharvy8v0rdsj', 'Staphylococcosis', 'staphylococcosis', 'Staphylococcosis is a bacterial disease of poultry caused mainly by Staphylococcus aureus. It occurs as systemic infections including septicemia and gangrenous dermatitis, or localized infections such as arthritis, tenosynovitis, osteomyelitis, and omphalitis. Economic losses result from decreased weight gain, mortality, carcass condemnation, and there is a potential risk for human food poisoning.', 'bacterium', 'Staphylococcus aureus', 'Staphylococcaceae', 'Staphylococcus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:16', '2026-06-24 21:19:16', NULL),
('01kvy2acsq5bmfzz30pyfjbchg', 'Streptococcosis in Poultry', 'streptococcosis-in-poultry', 'Streptococcosis is a bacterial disease of poultry caused by Streptococcus species that are part of the normal intestinal flora. The disease occurs as acute septicemic and chronic forms and may cause septicemia, joint disease, cellulitis, osteomyelitis, and endocarditis.', 'bacterium', 'Streptococcus species', 'Streptococcaceae', 'Streptococcus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:16', '2026-06-24 21:19:16', NULL),
('01kvy2ad0b4jsztekzy5h0jfq1', 'Syngamiasis', 'syngamiasis', 'A parasitic respiratory disease of poultry caused by Syngamus trachea. Adult male and female worms remain permanently attached in copulation, forming a characteristic Y-shape within the trachea and major bronchi, resulting in respiratory distress.', 'parasite', 'Syngamus trachea', 'Syngamidae', 'Syngamus', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:17', '2026-06-24 21:19:17', NULL),
('01kvy2ad4s45zkabx8aeqajvbf', 'T-2 Toxicosis', 't-2-toxicosis', 'T-2 toxicosis is a trichothecene mycotoxicosis caused by T-2 toxin produced by Fusarium tricinctum. The disease is characterized primarily by oral and digestive necrotic lesions, reduced feed intake, poor productivity, and neurological abnormalities.', 'mycotoxin', 'T-2 toxin', NULL, 'Fusarium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:17', '2026-06-24 21:19:17', NULL),
('01kvy2adaqn10pv18rqcs62daw', 'Thiamine Deficiency', 'thiamine-deficiency', 'A nutritional disorder caused by inadequate thiamine intake or increased destruction of thiamine, characterized by anorexia, ataxia, polyneuritis, paralysis, backward flexion of the head and neck, and death.', 'nutritional deficiency', 'Thiamine deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:17', '2026-06-24 21:19:17', NULL),
('01kvy2adkf5x16qd01az6cfb9b', 'Trichomoniasis', 'trichomoniasis', 'A protozoal disease of the upper digestive tract caused by Trichomonas gallinae. It is particularly severe in pigeons, especially squabs, and is characterized by caseous necrotic lesions in the mouth, throat, crop, and esophagus.', 'protozoa', 'Trichomonas gallinae', NULL, 'Trichomonas', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:17', '2026-06-24 21:19:17', NULL),
('01kvy2adtf7hmv9cde4mvnneh4', 'Turkey Coryza', 'turkey-coryza-bordetellosis', 'Turkey coryza (bordetellosis) is a highly contagious upper respiratory disease primarily affecting young turkeys and caused by Bordetella avium. The disease is characterized by sudden onset, colonization of ciliated epithelium, respiratory signs, submandibular edema, tracheal collapse, and stunted growth.', 'bacterium', 'Bordetella avium', 'Alcaligenaceae', 'Bordetella', '7-10 days', 80.00, 100.00, 5.00, 40.00, 0, '2026-06-24 21:19:17', '2026-06-24 21:19:17', NULL),
('01kvy2adzf7spzn80rtvcrn5fx', 'Turkey Hemorrhagic Enteritis', 'turkey-hemorrhagic-enteritis', 'A sudden adenoviral disease of turkeys characterized by increased mortality, depression, bloody droppings, and in the subclinical form by splenomegaly.', 'virus', 'Hemorrhagic Enteritis Virus', 'Adenoviridae', NULL, NULL, NULL, NULL, 5.00, 60.00, 0, '2026-06-24 21:19:18', '2026-06-24 21:19:18', NULL),
('01kvy2ae2phegs1gtjc10bj9pd', 'Ulcerative Enteritis', 'ulcerative-enteritis', 'Ulcerative enteritis is an acute bacterial disease of young chickens, turkeys, and game birds characterized by sudden onset, rapidly increasing mortality, and ulcerative lesions of the intestinal tract.', 'bacterium', 'Clostridium colinum', 'Clostridiaceae', 'Clostridium', NULL, NULL, NULL, 2.00, 100.00, 0, '2026-06-24 21:19:18', '2026-06-24 21:19:18', NULL),
('01kvy2aedn0gk5ttydarqr0fb7', 'Urolithiasis', 'urolithiasis', 'Urolithiasis is a multifactorial renal disorder seen primarily in caged laying hens and characterized by obstruction of one or both ureters by urates, resulting in renal lobe atrophy, renal dysfunction, and increased mortality.', 'multifactorial', 'Multifactorial metabolic and nutritional disorder', NULL, NULL, NULL, NULL, NULL, 2.00, 50.00, 0, '2026-06-24 21:19:18', '2026-06-24 21:19:18', NULL),
('01kvy2aem1f1f6ck7yxehp6757', 'Viral Arthritis', 'viral-arthritis', 'An infectious disease of chickens characterized by unilateral or bilateral swelling, thickening, and occasional rupture of the gastrocnemius tendon and thickening of the surrounding tendon sheath resulting in lameness.', 'virus', 'Avian Reovirus', 'Reoviridae', NULL, NULL, NULL, 100.00, NULL, 6.00, 0, '2026-06-24 21:19:18', '2026-06-24 21:19:18', NULL),
('01kvy2aeyfckfndn33a4cwpq6v', 'Vitamin A Deficiency', 'vitamin-a-deficiency', 'A nutritional disorder caused by inadequate vitamin A intake or increased destruction of vitamin A, characterized by poor growth, ocular lesions, respiratory signs, impaired immunity, and reproductive failure.', 'nutritional deficiency', 'Vitamin A deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:19', '2026-06-24 21:19:19', NULL),
('01kvy2af4202affd0stnp7bdb9', 'Vitamin B6 Deficiency', 'vitamin-b6-deficiency', 'A nutritional disorder caused by inadequate pyridoxine intake, characterized by poor growth, neurological disturbances, perosis, reduced feed intake, decreased egg production, and reduced hatchability. Increased dietary protein levels increase vitamin B6 requirements.', 'nutritional deficiency', 'Vitamin B6 deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:19', '2026-06-24 21:19:19', NULL),
('01kvy2af764nwc1kj2n76yb3v4', 'Vitamin D Deficiency', 'vitamin-d-deficiency', 'A nutritional disorder caused by inadequate vitamin D, calcium, phosphorus, or imbalance in calcium-phosphorus ratio, resulting in defective bone mineralization, skeletal deformities, poor eggshell quality, and impaired productivity.', 'nutritional deficiency', 'Vitamin D deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:19', '2026-06-24 21:19:19', NULL),
('01kvy2afe0t981097cd58hsv9t', 'Vitamin E Deficiency', 'vitamin-e-deficiency', 'A nutritional disorder caused by inadequate vitamin E intake or increased destruction of vitamin E due to oxidation of dietary unsaturated fats. Deficiency is associated with nutritional encephalomalacia, exudative diathesis, enzootic muscular dystrophy, infertility, embryonic mortality, and increased erythrocyte fragility.', 'nutritional deficiency', 'Vitamin E deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:19', '2026-06-24 21:19:19', NULL),
('01kvy2afh0ee18km65r9y117kt', 'Vitamin K Deficiency', 'vitamin-k-deficiency', 'A nutritional disorder caused by inadequate vitamin K availability, resulting in impaired blood coagulation, prolonged clotting time, hemorrhages, anemia, and increased embryonic mortality.', 'nutritional deficiency', 'Vitamin K deficiency', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:19', '2026-06-24 21:19:19', NULL),
('01kvy2afmm0pvgwshwtdethjt0', 'Water Deficiency', 'water-deficiency', 'A nutritional and metabolic disorder resulting from inadequate water supply in poultry, leading to impaired growth, reduced egg production, digestive disturbances, and urate deposition in visceral organs.', 'nutritional deficiency', 'Inadequate water intake', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:19', '2026-06-24 21:19:19', NULL),
('01kvy2afqm5h8rzkdbqc4dv7bb', 'Zearalenone Toxicosis', 'zearalenone-toxicosis', 'Zearalenone toxicosis is a mycotoxicosis caused by zearalenone, a Fusarium-derived mycotoxin with potent estrogenic activity. In poultry, high dietary levels alter reproductive and lymphoid organ weights.', 'mycotoxin', 'Zearalenone', NULL, 'Fusarium', NULL, NULL, NULL, NULL, NULL, 0, '2026-06-24 21:19:19', '2026-06-24 21:19:19', NULL);
INSERT INTO `disease_age_groups` (`id`, `disease_id`, `min_days`, `max_days`, `description`, `created_at`, `updated_at`) VALUES
(1, '01kvy1vfnyqn1vvtyn6e6dpbjs', 1, 14, 'Disease usually appears during the first two weeks of life.', '2026-06-24 21:11:08', '2026-06-24 21:11:08'),
(2, '01kvy1vfnyqn1vvtyn6e6dpbjs', 1, 42, 'Clinical disease may occur in chicks up to 6 weeks of age.', '2026-06-24 21:11:08', '2026-06-24 21:11:08'),
(3, '01kvy1vfnyqn1vvtyn6e6dpbjs', 15, NULL, 'Infection in birds older than 2-3 weeks is usually subclinical.', '2026-06-24 21:11:08', '2026-06-24 21:11:08'),
(4, '01kvy29s4yqaj4k1q8wwpk4bsb', NULL, NULL, 'Young birds and imported stocks are more susceptible to acute disease, whereas adult birds in endemic areas usually develop chronic disease.', '2026-06-24 21:18:57', '2026-06-24 21:18:57'),
(5, '01kvy29se5sete2dg0s3pzfkke', NULL, NULL, 'Young birds are more susceptible. White-Pekin ducklings are the most susceptible, while Japanese quails are the most resistant.', '2026-06-24 21:18:57', '2026-06-24 21:18:57'),
(6, '01kvy29sn82by5wzwj4nf8c3rh', NULL, NULL, 'Young birds are more susceptible to severe disease and mortality.', '2026-06-24 21:18:57', '2026-06-24 21:18:57'),
(7, '01kvy29sra1rj92hhmbbqndt5q', 21, 28, 'Young chicks are highly susceptible and may develop brooder pneumonia.', '2026-06-24 21:18:57', '2026-06-24 21:18:57'),
(8, '01kvy29sz4y4tverf5p4x6c0ac', NULL, NULL, 'All ages may be affected, with high mortality particularly in young birds.', '2026-06-24 21:18:57', '2026-06-24 21:18:57'),
(9, '01kvy1vfnyqn1vvtyn6e6dpbjs', 1, 14, 'Disease usually appears during the first two weeks of life.', '2026-06-24 21:18:58', '2026-06-24 21:18:58'),
(10, '01kvy1vfnyqn1vvtyn6e6dpbjs', 1, 42, 'Clinical disease may occur in chicks up to 6 weeks of age.', '2026-06-24 21:18:58', '2026-06-24 21:18:58'),
(11, '01kvy1vfnyqn1vvtyn6e6dpbjs', 15, NULL, 'Infection in birds older than 2-3 weeks is usually subclinical.', '2026-06-24 21:18:58', '2026-06-24 21:18:58'),
(12, '01kvy29tdf0fca9k3450mnnkjj', NULL, NULL, 'Young birds are generally more susceptible than mature birds.', '2026-06-24 21:18:58', '2026-06-24 21:18:58'),
(13, '01kvy29tdf0fca9k3450mnnkjj', NULL, 90, 'Chickens under 3 months of age may experience high mortality in the presence of concomitant infections.', '2026-06-24 21:18:58', '2026-06-24 21:18:58'),
(14, '01kvy29tk978fng2j0ph7nnbc4', NULL, NULL, 'All ages are susceptible.', '2026-06-24 21:18:58', '2026-06-24 21:18:58'),
(15, '01kvy29tqzhr48ywajaqbse84y', NULL, NULL, 'All ages and sexes are susceptible.', '2026-06-24 21:18:58', '2026-06-24 21:18:58'),
(16, '01kvy29v2jzd2cer8fkda9wd30', NULL, NULL, 'Adult birds and heavier breeds are most frequently affected.', '2026-06-24 21:18:58', '2026-06-24 21:18:58'),
(17, '01kvy29v69ephyz1wea1z94kzb', NULL, NULL, 'Birds of all ages are susceptible, although young birds are more susceptible.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(18, '01kvy29ve7891jnq459ac1j9mv', NULL, NULL, 'All ages are susceptible, but clinical disease and lesions are most common in older birds because of the slow progression of the disease.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(19, '01kvy29vqy44p87zhatv661zj0', NULL, NULL, 'Birds of all ages are susceptible.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(20, '01kvy29vwn8t4ayhx6p9j3sz38', NULL, 90, 'Young birds are more susceptible. In turkeys, over 80% of infections occur during the first 3 months of life.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(21, '01kvy29w29pdczsfp1c0bnd3nn', NULL, NULL, 'Feather pecking may occur at any age.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(22, '01kvy29w29pdczsfp1c0bnd3nn', NULL, NULL, 'Toe picking is most common in young chicks.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(23, '01kvy29w5ab8c9nrpe0mx27jz3', NULL, NULL, 'Birds of all ages are susceptible.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(24, '01kvy29w71bj56avhtqzv24ch4', NULL, NULL, 'Chicks readily utilize starch and sucrose but tolerate only limited amounts of lactose.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(25, '01kvy29w7xpfgdxh0b4tstxjyc', NULL, NULL, 'Birds of all ages are susceptible.', '2026-06-24 21:18:59', '2026-06-24 21:18:59'),
(26, '01kvy29w97kx9smz6c8gf3rzgp', NULL, NULL, 'Birds of all ages are susceptible.', '2026-06-24 21:19:00', '2026-06-24 21:19:00'),
(27, '01kvy29wbsxz9n1pr7en38kxr4', 1, 21, 'The most severe effects occur during the first three weeks of life.', '2026-06-24 21:19:00', '2026-06-24 21:19:00'),
(28, '01kvy29wbsxz9n1pr7en38kxr4', NULL, NULL, 'All ages are susceptible, but young chicks are most severely affected.', '2026-06-24 21:19:00', '2026-06-24 21:19:00'),
(29, '01kvy29wgpk3jbp92pke9ppb6w', NULL, NULL, 'Young chicks and turkey poults are highly susceptible.', '2026-06-24 21:19:00', '2026-06-24 21:19:00'),
(30, '01kvy29wr8fnb9krhsht7czw0s', NULL, NULL, 'Birds of all ages are susceptible.', '2026-06-24 21:19:00', '2026-06-24 21:19:00'),
(31, '01kvy29x4fbe4pg133nw317z6c', NULL, NULL, 'Young birds are primarily affected, with turkey poults being more susceptible than chicks.', '2026-06-24 21:19:01', '2026-06-24 21:19:01'),
(32, '01kvy29x9tps5z748dvtpq01ha', NULL, NULL, 'Turkeys are the most sensitive species to citrinin toxicity.', '2026-06-24 21:19:01', '2026-06-24 21:19:01'),
(33, '01kvy29xc145rd8fgmdfk9tfpt', NULL, NULL, 'Birds of all ages may be affected by dietary cobalamin deficiency.', '2026-06-24 21:19:01', '2026-06-24 21:19:01'),
(34, '01kvy29xc145rd8fgmdfk9tfpt', NULL, NULL, 'Embryos from deficient breeder hens are highly susceptible.', '2026-06-24 21:19:01', '2026-06-24 21:19:01'),
(35, '01kvy29xj7f2q94crg652fxsze', NULL, NULL, 'Occurs most frequently in chickens surviving an outbreak of coli septicemia.', '2026-06-24 21:19:01', '2026-06-24 21:19:01'),
(36, '01kvy29xna2jeggsspnazx35fd', NULL, NULL, 'Occurs mainly in hens toward the termination of the laying period.', '2026-06-24 21:19:01', '2026-06-24 21:19:01'),
(37, '01kvy29xsjq4y30wgz1w5txmp9', 28, 70, 'Disease occurs more frequently in broiler chickens between 4 and 10 weeks of age.', '2026-06-24 21:19:01', '2026-06-24 21:19:01'),
(38, '01kvy29xsjq4y30wgz1w5txmp9', 0, 14, 'May occur in chicks up to 2 weeks of age.', '2026-06-24 21:19:01', '2026-06-24 21:19:01'),
(39, '01kvy29y5j4q4rfrznr1zxt1mq', NULL, NULL, 'No specific age susceptibility was reported. Poultry are less susceptible than swine.', '2026-06-24 21:19:02', '2026-06-24 21:19:02'),
(40, '01kvy29yan3svqp1kbpmf5phwr', NULL, NULL, 'Birds of all ages are susceptible.', '2026-06-24 21:19:02', '2026-06-24 21:19:02'),
(41, '01kvy29yeeaz4cyszpnqqdf8e0', 1, 14, 'Highly susceptible with severe disease and high mortality', '2026-06-24 21:19:02', '2026-06-24 21:19:02'),
(42, '01kvy29yeeaz4cyszpnqqdf8e0', 28, 42, 'Age resistance becomes complete', '2026-06-24 21:19:02', '2026-06-24 21:19:02'),
(43, '01kvy29yjr0rc4cfa0p6tw325m', 6, 42, 'Young ducks are affected', '2026-06-24 21:19:02', '2026-06-24 21:19:02'),
(44, '01kvy29yvk239gn286tps2tt87', NULL, NULL, 'Laying hens and breeders are primarily affected around peak egg production.', '2026-06-24 21:19:02', '2026-06-24 21:19:02'),
(45, '01kvy29yykkvafg4xwxrrxx89m', NULL, NULL, 'Not specified.', '2026-06-24 21:19:02', '2026-06-24 21:19:02'),
(46, '01kvy29z0pg6pmf40bmngv4wh3', 14, 35, 'Most commonly occurs in ducklings between 2 and 5 weeks of age.', '2026-06-24 21:19:02', '2026-06-24 21:19:02'),
(47, '01kvy29z517wr0g79kakgczkeb', NULL, NULL, 'No age susceptibility was specified.', '2026-06-24 21:19:03', '2026-06-24 21:19:03'),
(48, '01kvy29z9p0rpacyhm3x4vb3s2', 90, 180, 'Usually detected in birds between 3 and 6 months of age.', '2026-06-24 21:19:03', '2026-06-24 21:19:03'),
(49, '01kvy29zfz6erz11587c9dr9r4', NULL, NULL, 'Growing chicks require approximately 1.5% dietary linoleic acid for normal growth.', '2026-06-24 21:19:03', '2026-06-24 21:19:03'),
(50, '01kvy29zk7rt7jp5rqpstjhmma', 21, 42, 'Usually occurs in chickens and turkey poults between 3 and 6 weeks of age.', '2026-06-24 21:19:03', '2026-06-24 21:19:03'),
(51, '01kvy29zra51g98zf1qhmxv82b', NULL, NULL, 'Young chicks and turkey poults are most susceptible because of their rapid growth rate.', '2026-06-24 21:19:03', '2026-06-24 21:19:03'),
