(171, '01kvy2aeyfckfndn33a4cwpq6v', NULL, NULL, 'Semi-mature and adult chickens, turkeys, and ducks may also be affected.', '2026-06-24 21:19:19', '2026-06-24 21:19:19'),
(172, '01kvy2af4202affd0stnp7bdb9', NULL, NULL, 'Young chicks and poults are susceptible to neurological manifestations.', '2026-06-24 21:19:19', '2026-06-24 21:19:19'),
(173, '01kvy2af4202affd0stnp7bdb9', NULL, NULL, 'Adult birds may develop reproductive and production losses.', '2026-06-24 21:19:19', '2026-06-24 21:19:19'),
(174, '01kvy2af764nwc1kj2n76yb3v4', 0, 126, 'Growing chicks from hatch to 18 weeks are susceptible to rickets.', '2026-06-24 21:19:19', '2026-06-24 21:19:19'),
(175, '01kvy2af764nwc1kj2n76yb3v4', NULL, NULL, 'Adult confined laying hens are susceptible to osteomalacia and cage layer fatigue.', '2026-06-24 21:19:19', '2026-06-24 21:19:19'),
(176, '01kvy2afe0t981097cd58hsv9t', 10, 42, 'Nutritional encephalomalacia usually affects chicks between 10 days and 6 weeks of age.', '2026-06-24 21:19:19', '2026-06-24 21:19:19'),
(177, '01kvy2afh0ee18km65r9y117kt', NULL, NULL, 'All ages are susceptible when dietary vitamin K is inadequate.', '2026-06-24 21:19:19', '2026-06-24 21:19:19'),
(178, '01kvy2afmm0pvgwshwtdethjt0', NULL, NULL, 'All poultry species and ages are susceptible; chicks require continuous access to water because they drink small amounts frequently.', '2026-06-24 21:19:19', '2026-06-24 21:19:19'),
(179, '01kvy2afqm5h8rzkdbqc4dv7bb', NULL, NULL, 'No specific age susceptibility was reported.', '2026-06-24 21:19:19', '2026-06-24 21:19:19');
